    from typing import List
    saved = 0
    for month in range(12):
        budget = budgets[month]
        if budget > 300:
            return -(month + 1)
        remaining = 300 - budget
        if remaining >= 100:
            save_amount = (remaining // 100) * 100
            saved += save_amount
    total = saved * 1.2 + 0
    return int(total)

