def min_groups(w, n, prices):
    prices.sort()
    left = 0
    right = n - 1
    groups = 0
    while left <= right:
        if left == right:
            groups += 1
            break
        if prices[left] + prices[right] <= w:
            left += 1
            right -= 1
        else:
            right -= 1
        groups += 1
    return groups

